 void ToggleExit(){if(!config.ExitLookupEnabled&&!ConfirmLookup("启用后会访问 https://ipwho.is/ 查询属地，服务会收到公网出口 IP 和常规 HTTPS 请求信息，不发送文件或通知。仅卡片打开时每60秒刷新。是否启用？"))return;config.ExitLookupEnabled=!config.ExitLookupEnabled;if(save!=null)save();exitSwitch.Content=config.ExitLookupEnabled?"监测已开启":"开启出口监测";exitSwitch.Tag=config.ExitLookupEnabled?"active":null;if(config.ExitLookupEnabled)RefreshExit();else exitState.Text="监测已暂停 · 上方如有读数为历史记录";}
 void ShowExit(NetworkExit result){country.Text=result.Country;try{if(!String.IsNullOrEmpty(result.CountryCode))country.Text=new System.Globalization.RegionInfo(result.CountryCode).DisplayName;}catch(ArgumentException){}string code=(result.CountryCode??"").ToLowerInvariant();string path=code.Length==2&&code.All(Char.IsLetter)?Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"flags",code+".png"):"";flag.Source=File.Exists(path)?ImageFrom(path):null;flagPlaceholder.Visibility=flag.Source==null?Visibility.Visible:Visibility.Collapsed;exitText.Text=result.Ip+"\n"+String.Join(" · ",new[]{result.Region,result.City,result.Isp}.Where(x=>!String.IsNullOrEmpty(x)).Distinct());}
